; calls.asm -- chapter 16: five BIOS calls, and the ports
; generated by gen16.py
        INCLUDE "msx.inc"
        OUTPUT "calls.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
RESULTS EQU RAM_START          ; what the program found: the debugger reads it here
; Five BIOS calls, each with every register it does not take set to a mark
; first; then the same jobs through the ports. The debugger stops before and
; after each call and reads the registers and the system variables.
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off while the page is drawn
        VDP_REG 0, $00          ; Graphic I: 32 x 24 characters
        VDP_REG 2, $06          ; names              $1800
        VDP_REG 3, $80          ; colours            $2000
        VDP_REG 4, $00          ; patterns           $0000
        VDP_REG 5, $36          ; sprite attributes  $1B00
        VDP_REG 6, $07          ; sprite patterns    $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; the BIOS character set: 256 x 8 bytes
        ld hl, (CGTABL)
        ld bc, 2048
.font:  ld a, (hl)
        out (VDP_DATA), a
        inc hl
        dec bc
        ld a, b
        or c
        jr nz, .font
        VRAM_WRITE $0008        ; characters 1 and 2: the bit boxes
        ld hl, boxes
        ld b, 16
.box:   ld a, (hl)
        out (VDP_DATA), a
        inc hl
        djnz .box
        VRAM_WRITE $2000        ; colours: black ink (1) on white paper (15)
        ld b, 32
        ld a, $1F
.col:   out (VDP_DATA), a
        djnz .col
        VRAM_WRITE $1800        ; names: all spaces
        ld bc, 768
.clr:   ld a, ' '
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, .clr
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
pg:     nop                     ; the page set up through the ports
        ld a, BLACK
        ld (FORCLR), a          ; ink
        ld a, WHITE
        ld (BAKCLR), a          ; paper
        ld a, LIGHT_GREEN
        ld (BDRCLR), a          ; border
        call marks
        ld a, 1                 ; screen 1
b1:     call CHGMOD
a1:     di                      ; the interrupts off again, whatever the call did
        call marks
        ld a, 'A'
b2:     call CHPUT
a2:     di                      ; the interrupts off again, whatever the call did
        call marks
        ld b, LIGHT_GREEN
        ld c, 7                 ; the border
b3:     call WRTVDP
a3:     di                      ; the interrupts off again, whatever the call did
        call marks
        ld hl, cells
        ld de, $1800            ; the name table
        ld bc, 768
b4:     call LDIRVM
a4:     di                      ; the interrupts off again, whatever the call did
        call marks
        xor a                   ; the cursor keys
b5:     call GTSTCK
a5:     di                      ; the interrupts off again, whatever the call did
q3:     VDP_REG 7, LIGHT_GREEN  ; WRTVDP's job, through the port
q3e:    VDP_REG 1, $A0          ; display off: OTIR is too fast for it on (chapter 20)
q4:     VRAM_WRITE $1800        ; LDIRVM's, with OTIR (chapter 13)
        ld hl, cells
        ld c, VDP_DATA
        ld b, 0
        otir
        otir
        otir                    ; 3 x 256 bytes
q5:     call stick              ; GTSTCK's, from the keyboard
q2:     ld a, 'A'
        ld b, 0
        ld c, 0
        call putc               ; CHPUT's, with chapter 14's putc
q6:     nop
stop:   jr stop

; marks: every register a call does not take, set to a value of its own, so
; that what the call changes shows
marks:  exx
        ld bc, $B1B1
        ld de, $D1D1
        ld hl, $E1E1
        exx
        ex af, af'
        ld a, $A1
        ex af, af'
        ld ix, $1E1E
        ld iy, $1F1F
        ld bc, $B0B0
        ld de, $D0D0
        ld hl, $E0E0
        ret

; stick: A = the direction of the cursor keys, 0 to 8, as GTSTCK gives it:
;        row 8 of the keyboard, read through the PPI (chapter 3), and its four
;        top bits, which are 0 for a key held down, looked up in a table.
;        Uses A, H, L.
stick:  in a, (PPI_C)
        and $F0                 ; keep the PPI's other outputs
        or 8                    ; row 8: the cursor keys in bits 4 to 7
        out (PPI_C), a
        in a, (PPI_B)
        rrca
        rrca
        rrca
        rrca
        and $0F                 ; right, down, up, left: 0 when held
        ld l, a
        ld h, high sticks
        ld a, (hl)
        ret

        ALIGN 256               ; stick puts the four bits in L
sticks: db 0, 3, 5, 4, 1, 2, 0, 3, 7, 0, 6, 5, 8, 1, 7, 0

cells:  DUP 768, n              ; 768 characters for the name table
        db 32 + n % 96
        EDUP

; at: B = row (0-23), C = column (0-31) -> the VDP's write address is that
;     cell of the name table. Keeps BC, DE. Uses A, HL.
at:     push de
        ld l, b
        ld h, 0
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl              ; row x 32
        ld e, c
        ld d, $18
        add hl, de              ; + $1800 + column
        ld a, l
        out (VDP_CTRL), a
        ld a, h
        or $40
        out (VDP_CTRL), a
        pop de
        ret

; putc: A = character, B = row, C = column. Keeps BC, DE, HL.
putc:   push hl
        push af
        call at
        pop af
        out (VDP_DATA), a
        pop hl
        ret

; puts: HL = text ending in 0, B = row, C = column; C moves on.
puts:   ld a, (hl)
        or a
        ret z
        call putc
        inc hl
        inc c
        jr puts

; puthex: A = a byte, as two hexadecimal digits; C moves on by 2.
puthex: push af
        rrca
        rrca
        rrca
        rrca                    ; the high four bits first
        call hexdig
        pop af
hexdig: and %00001111
        add a, '0'
        cp '9' + 1
        jr c, .digit
        add a, 'A' - '9' - 1    ; 10-15 become A-F
.digit: call putc
        inc c
        ret
boxes:                          ; characters 1 (empty box) and 2 (filled)
        db %11111110, %10000010, %10000010, %10000010, %10000010, %10000010, %11111110, %00000000
        db %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %00000000
        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
